    public class BRBranchsController : BaseBusinessController
    {
        public BRBranchsController()
        {
            dal = new DALBaseProvider("BRBranchs", typeof(BRBranchsInfo));
        }

        /// <summary>
        /// Get central branch
        /// </summary>
        /// <returns>Branch object</returns>
        public BRBranchsInfo GetCentre()
        {
            BRBranchsController objBranchesController = new BRBranchsController();
            List<BRBranchsInfo> branches = GetBranchesByType(BranchType.Central.ToString());
            if (branches.Count > 0)
            {
                return branches[0];
            }
            return null;
        }

        /// <summary>
        /// Get branches by given type
        /// </summary>
        /// <param name="type">Given type</param>
        /// <returns>List of branches</returns>
        public List<BRBranchsInfo> GetBranchesByType(string type)
        {
            DataSet ds = GetAllObjects();
            List<BRBranchsInfo> branches = new List<BRBranchsInfo>();
            if (ds.Tables.Count > 0)
            {
                foreach (DataRow row in ds.Tables[0].Rows)
                {
                    BRBranchsInfo objBranchsInfo = (BRBranchsInfo)GetObjectFromDataRow(row);
                    if (objBranchsInfo.BRBranchType == type)
                    {
                        branches.Add(objBranchsInfo);
                    }
                }
            }
            return branches;
        }

        /// <summary>
        /// Get the current branch
        /// </summary>
        /// <returns>Branch object</returns>
        public BRBranchsInfo GetCurrentBranch()
        {
            return (BRBranchsInfo)dal.GetDataObject("BRBranchs_GetCurrentBranch");
        }

        /// <summary>
        /// Get all branches
        /// </summary>
        /// <returns>List of branches</returns>
        public List<BRBranchsInfo> GetAllBranches()
        {
            DataSet ds = GetAllObjects();
            return ((List<BRBranchsInfo>)GetListFromDataSet(ds)).Where(p => p.BRBranchID > 0).ToList();
        }

        /// <summary>
        /// Get all branches belonging to a location
        /// </summary>
        /// <param name="locationID">Location id</param>
        /// <returns>List of branches</returns>
        public List<BRBranchsInfo> GetBranchesByLocationID(int locationID)
        {
            DataSet ds = dal.GetDataSet("BRBranchs_GetBranchesByLocationID", locationID);
            return (List<BRBranchsInfo>)GetListFromDataSet(ds);
        }

        public override System.Collections.IList GetListFromDataSet(DataSet ds)
        {
            List<BRBranchsInfo> branches = new List<BRBranchsInfo>();
            if (ds.Tables.Count > 0)
            {
                foreach (DataRow row in ds.Tables[0].Rows)
                {
                    BRBranchsInfo branch = (BRBranchsInfo)GetObjectFromDataRow(row);
                    branches.Add(branch);
                }
            }
            return branches;
        }

        /// <summary>
        /// Get the full address from some address fields
        /// </summary>
        /// <returns>Full address</returns>
        public string GetFullAddress(BRBranchsInfo objBranchsInfo)
        {
            string address = string.Empty;
            if (!string.IsNullOrEmpty(objBranchsInfo.BRBranchContactAddressLine1))
            {
                address += objBranchsInfo.BRBranchContactAddressLine1 + ",";
            }
            if (!string.IsNullOrEmpty(objBranchsInfo.BRBranchContactAddressCity))
            {
                address += objBranchsInfo.BRBranchContactAddressCity + ",";
            }
            if (!string.IsNullOrEmpty(objBranchsInfo.BRBranchContactAddressStateProvince))
            {
                address += objBranchsInfo.BRBranchContactAddressStateProvince + ",";
            }
            if (!string.IsNullOrEmpty(objBranchsInfo.BRBranchContactAddressCountry))
            {
                address += objBranchsInfo.BRBranchContactAddressCountry + ",";
            }
            return address;
        }
